-- ============================================================
-- USERS
-- ============================================================
CREATE TABLE users (
    user_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    forenames VARCHAR(100) NOT NULL,
    surname VARCHAR(100) NOT NULL,
    phone_number VARCHAR(30),
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT ck_users_active CHECK (is_active IN ('Y','N'))
);

COMMENT ON TABLE users IS 'Stores application user accounts';

-- ============================================================
-- CUSTOMER PROFILES
-- ============================================================
CREATE TABLE customer_profiles (
    customer_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL UNIQUE,
    date_of_birth DATE,
    gender VARCHAR(20),
    current_loyalty_points INTEGER DEFAULT 0 NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT fk_customer_profile_user FOREIGN KEY (user_id)
        REFERENCES users(user_id),
    CONSTRAINT ck_customer_loyalty CHECK (current_loyalty_points >= 0)
);
CREATE INDEX idx_customer_profiles_gender ON customer_profiles(gender);
CREATE INDEX idx_customer_profiles_loyalty_points ON customer_profiles(current_loyalty_points DESC);

-- ============================================================
-- USER ROLES
-- ============================================================
CREATE TABLE user_roles (
    role_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_name VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(255),
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_user_roles_active CHECK (is_active IN ('Y','N'))
);
INSERT INTO user_roles(role_name,description) VALUES
('ADMIN','System Administrator with full access'),
('MANAGER','Manager with administrative privileges'),
('CUSTOMER','Regular customer with basic access'),
('STAFF','Cinema staff with operational access');

CREATE TABLE user_role_assignments (
    user_id BIGINT NOT NULL,
    role_id BIGINT NOT NULL,
    assigned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    assigned_by BIGINT,
    CONSTRAINT pk_user_role_assignments PRIMARY KEY(user_id,role_id),
    CONSTRAINT fk_ura_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_ura_role FOREIGN KEY(role_id) REFERENCES user_roles(role_id) ON DELETE CASCADE,
    CONSTRAINT fk_ura_assigned_by FOREIGN KEY(assigned_by) REFERENCES users(user_id) ON DELETE SET NULL
);

-- ============================================================
-- CINEMAS
-- ============================================================
CREATE TABLE cinemas (
    cinema_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cinema_name VARCHAR(150) NOT NULL,
    description VARCHAR(500),
    address VARCHAR(500),
    city VARCHAR(100),
    region VARCHAR(100),
    phone_number VARCHAR(30),
    email VARCHAR(150),
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT ck_cinemas_active CHECK(is_active IN('Y','N'))
);

