-- ============================================================
-- SCREENS
-- ============================================================
CREATE TABLE screens (
    screen_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cinema_id BIGINT NOT NULL,
    screen_name VARCHAR(100) NOT NULL,
    screen_number INTEGER NOT NULL,
    capacity INTEGER NOT NULL,
    screen_type VARCHAR(50),
    sound_system VARCHAR(100),
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT fk_screens_cinema FOREIGN KEY(cinema_id) REFERENCES cinemas(cinema_id),
    CONSTRAINT uk_screen_number UNIQUE(cinema_id,screen_number),
    CONSTRAINT ck_screens_capacity CHECK(capacity > 0),
    CONSTRAINT ck_screens_active CHECK(is_active IN('Y','N'))
);

