-- ============================================================
-- SEATS
-- ============================================================
CREATE TABLE seats (
    seat_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    screen_id BIGINT NOT NULL,
    row_label VARCHAR(10) NOT NULL,
    seat_number INTEGER NOT NULL,
    seat_label VARCHAR(20) NOT NULL,
    seat_type VARCHAR(30) DEFAULT 'STANDARD',
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT fk_seats_screen FOREIGN KEY(screen_id) REFERENCES screens(screen_id),
    CONSTRAINT uk_seat_position UNIQUE(screen_id,row_label,seat_number),
    CONSTRAINT uk_seat_label UNIQUE(screen_id,seat_label),
    CONSTRAINT ck_seats_active CHECK(is_active IN('Y','N'))
);
CREATE INDEX idx_seats_screen_id ON seats(screen_id);
CREATE INDEX idx_seats_seat_type ON seats(seat_type);
CREATE INDEX idx_seats_active ON seats(is_active);

-- 5 rows x 10 seats for Screen 1; 2 wheelchair positions.
INSERT INTO seats(screen_id,row_label,seat_number,seat_label,seat_type)
SELECT 1, chr(64+r), s, chr(64+r)||s::text,
       CASE WHEN s IN(5,6) THEN 'VIP' ELSE 'STANDARD' END
FROM generate_series(1,5) AS r
CROSS JOIN generate_series(1,10) AS s;
INSERT INTO seats(screen_id,row_label,seat_number,seat_label,seat_type) VALUES
(1,'W',1,'W1','WHEELCHAIR'),(1,'W',2,'W2','WHEELCHAIR');

-- ============================================================
-- STAFF PROFILES
-- ============================================================
CREATE TABLE staff_profiles (
    staff_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL UNIQUE,
    employee_number VARCHAR(50) NOT NULL UNIQUE,
    job_title VARCHAR(100),
    department VARCHAR(100),
    hire_date DATE,
    cinema_id BIGINT,
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT fk_staff_user FOREIGN KEY(user_id) REFERENCES users(user_id),
    CONSTRAINT fk_staff_cinema FOREIGN KEY(cinema_id) REFERENCES cinemas(cinema_id),
    CONSTRAINT ck_staff_active CHECK(is_active IN('Y','N'))
);

