-- ============================================================
-- PEOPLE
-- ============================================================
CREATE TABLE people (
    person_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tmdb_person_id INTEGER UNIQUE,
    name VARCHAR(200) NOT NULL,
    original_name VARCHAR(200),
    profile_url VARCHAR(500),
    gender INTEGER,
    known_for_department VARCHAR(100),
    popularity NUMERIC(10,3),
    biography TEXT,
    birth_date DATE,
    death_date DATE,
    place_of_birth VARCHAR(300),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6)
);

-- ============================================================
-- MOVIES
-- ============================================================
CREATE TABLE movies (
    movie_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tmdb_id INTEGER UNIQUE,
    title VARCHAR(200) NOT NULL,
    original_title VARCHAR(200),
    description TEXT,
    release_date DATE,
    runtime_minutes INTEGER,
    age_rating VARCHAR(20),
    poster_url VARCHAR(500),
    backdrop_url VARCHAR(500),
    trailer_url VARCHAR(500),
    rating NUMERIC(3,1),
    status VARCHAR(30) DEFAULT 'UPCOMING' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    studio_id BIGINT,
    run_ends_on DATE,
    CONSTRAINT fk_movies_studio FOREIGN KEY(studio_id) REFERENCES studios(studio_id),
    CONSTRAINT ck_movies_rating CHECK(rating IS NULL OR(rating >= 0 AND rating <= 10)),
    CONSTRAINT ck_movies_status CHECK(status IN('UPCOMING','NOW_SHOWING','ENDED','ARCHIVED')),
    CONSTRAINT ck_movies_run_ends CHECK(run_ends_on IS NULL OR release_date IS NULL OR run_ends_on >= release_date)
);
CREATE INDEX idx_movies_tmdb_id ON movies(tmdb_id);
CREATE INDEX idx_movies_status ON movies(status);
CREATE INDEX idx_movies_release_date ON movies(release_date);

-- ============================================================
-- MOVIE GENRES / CAST / CREW / VIDEOS / IMAGES
-- ============================================================
CREATE TABLE movie_genres (
    movie_id BIGINT NOT NULL,
    genre_id BIGINT NOT NULL,
    PRIMARY KEY(movie_id,genre_id),
    FOREIGN KEY(movie_id) REFERENCES movies(movie_id) ON DELETE CASCADE,
    FOREIGN KEY(genre_id) REFERENCES genres(genre_id)
);
CREATE INDEX idx_movie_genres_genre ON movie_genres(genre_id);

CREATE TABLE movie_cast (
    movie_cast_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_id BIGINT NOT NULL REFERENCES movies(movie_id),
    person_id BIGINT NOT NULL REFERENCES people(person_id),
    character_name VARCHAR(300),
    cast_order INTEGER,
    credit_id VARCHAR(100),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uk_movie_cast UNIQUE(movie_id,person_id,character_name)
);
CREATE INDEX idx_movie_cast_movie ON movie_cast(movie_id);
CREATE INDEX idx_movie_cast_person ON movie_cast(person_id);

CREATE TABLE movie_crew (
    movie_crew_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_id BIGINT NOT NULL REFERENCES movies(movie_id),
    person_id BIGINT NOT NULL REFERENCES people(person_id),
    department VARCHAR(100),
    job VARCHAR(200),
    credit_id VARCHAR(100),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT uk_movie_crew UNIQUE(movie_id,person_id,job)
);
CREATE INDEX idx_movie_crew_movie ON movie_crew(movie_id);
CREATE INDEX idx_movie_crew_person ON movie_crew(person_id);

CREATE TABLE movie_videos (
    video_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_id BIGINT NOT NULL REFERENCES movies(movie_id),
    tmdb_video_id VARCHAR(100) UNIQUE,
    video_name VARCHAR(300) NOT NULL,
    video_key VARCHAR(200) NOT NULL,
    site VARCHAR(50),
    video_type VARCHAR(50),
    official CHAR(1) DEFAULT 'N' NOT NULL,
    published_at TIMESTAMP(6),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_movie_videos_official CHECK(official IN('Y','N'))
);
CREATE INDEX idx_movie_videos_movie ON movie_videos(movie_id);

CREATE TABLE movie_images (
    image_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_id BIGINT NOT NULL REFERENCES movies(movie_id),
    image_type VARCHAR(30) NOT NULL,
    file_path VARCHAR(500) NOT NULL,
    image_url VARCHAR(700),
    width INTEGER,
    height INTEGER,
    aspect_ratio NUMERIC(10,4),
    language VARCHAR(20),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_movie_images_type CHECK(image_type IN('POSTER','BACKDROP','LOGO'))
);
CREATE INDEX idx_movie_images_movie ON movie_images(movie_id);

-- ============================================================
-- PRODUCTION COMPANIES
-- ============================================================
CREATE TABLE production_companies (
    company_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tmdb_company_id INTEGER UNIQUE,
    company_name VARCHAR(300) NOT NULL,
    logo_url VARCHAR(500),
    country_code VARCHAR(10),
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6)
);

CREATE TABLE movie_production_companies (
    movie_id BIGINT NOT NULL,
    company_id BIGINT NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY(movie_id,company_id),
    FOREIGN KEY(movie_id) REFERENCES movies(movie_id),
    FOREIGN KEY(company_id) REFERENCES production_companies(company_id)
);
CREATE INDEX idx_movie_prod_comp_company ON movie_production_companies(company_id);

-- ============================================================
-- SHOWTIMES
-- ============================================================
-- Composite uniqueness needed by fk_showtimes_screen_cinema below.
-- (Must exist before showtimes is created, or a fresh install fails.)
ALTER TABLE screens ADD CONSTRAINT uk_screens_id_cinema UNIQUE(screen_id,cinema_id);

CREATE TABLE showtimes (
    showtime_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    movie_id BIGINT NOT NULL REFERENCES movies(movie_id),
    cinema_id BIGINT NOT NULL REFERENCES cinemas(cinema_id),
    screen_id BIGINT NOT NULL REFERENCES screens(screen_id),
    show_date DATE NOT NULL,
    start_time TIMESTAMP NOT NULL,
    end_time TIMESTAMP,
    ticket_price NUMERIC(10,2) NOT NULL,
    status VARCHAR(30) DEFAULT 'SCHEDULED' NOT NULL,
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    CONSTRAINT ck_showtimes_price CHECK(ticket_price >= 0),
    CONSTRAINT ck_showtimes_status CHECK(status IN('SCHEDULED','NOW_SHOWING','COMPLETED','CANCELLED')),
    CONSTRAINT ck_showtimes_active CHECK(is_active IN('Y','N')),
    CONSTRAINT fk_showtimes_screen_cinema FOREIGN KEY(screen_id,cinema_id)
        REFERENCES screens(screen_id,cinema_id) DEFERRABLE INITIALLY IMMEDIATE
);


CREATE INDEX idx_showtimes_movie_id ON showtimes(movie_id);
CREATE INDEX idx_showtimes_cinema_id ON showtimes(cinema_id);
CREATE INDEX idx_showtimes_screen_id ON showtimes(screen_id);
CREATE INDEX idx_showtimes_show_date ON showtimes(show_date);
CREATE INDEX idx_showtimes_start_time ON showtimes(start_time);
CREATE INDEX idx_showtimes_status ON showtimes(status);
CREATE INDEX idx_showtimes_active ON showtimes(is_active);
CREATE INDEX idx_showtimes_date_status ON showtimes(show_date,status);
CREATE INDEX idx_showtimes_cinema_date ON showtimes(cinema_id,show_date);

-- ============================================================
-- TICKET PRICES
-- ============================================================
CREATE TABLE ticket_prices (
    price_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cinema_id BIGINT NOT NULL REFERENCES cinemas(cinema_id),
    screen_id BIGINT REFERENCES screens(screen_id),
    price_name VARCHAR(100) NOT NULL,
    ticket_type VARCHAR(30) NOT NULL,
    amount NUMERIC(10,2) NOT NULL,
    currency VARCHAR(10) DEFAULT 'GHS' NOT NULL,
    day_type VARCHAR(20),
    start_time TIMESTAMP(6),
    end_time TIMESTAMP(6),
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6),
    CONSTRAINT ck_ticket_prices_amount CHECK(amount >= 0),
    CONSTRAINT ck_ticket_prices_active CHECK(is_active IN('Y','N'))
);
