-- ============================================================
-- PROMOTIONS
-- ============================================================
CREATE TABLE promotions (
    promotion_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cinema_id BIGINT REFERENCES cinemas(cinema_id),
    promotion_name VARCHAR(150) NOT NULL,
    promotion_code VARCHAR(50) UNIQUE,
    description VARCHAR(1000),
    discount_type VARCHAR(20) NOT NULL,
    discount_value NUMERIC(10,2) NOT NULL,
    min_tickets INTEGER,
    max_discount NUMERIC(10,2),
    start_date TIMESTAMP(6) NOT NULL,
    end_date TIMESTAMP(6) NOT NULL,
    is_active CHAR(1) DEFAULT 'Y' NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP(6),
    CONSTRAINT ck_promotions_discount_type CHECK(discount_type IN('PERCENTAGE','FIXED')),
    CONSTRAINT ck_promotions_discount_value CHECK(discount_value >= 0),
    CONSTRAINT ck_promotions_min_tickets CHECK(min_tickets IS NULL OR min_tickets > 0),
    CONSTRAINT ck_promotions_max_discount CHECK(max_discount IS NULL OR max_discount >= 0),
    CONSTRAINT ck_promotions_status CHECK(is_active IN('Y','N')),
    CONSTRAINT ck_promotions_dates CHECK(end_date >= start_date)
);
