CREATE TABLE promotion_targets (
    target_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    promotion_id BIGINT NOT NULL REFERENCES promotions(promotion_id),
    target_type VARCHAR(30) NOT NULL,
    target_value VARCHAR(100) NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_promotion_target_type CHECK(target_type IN('MOVIE','TICKET_TYPE','SCREEN','CINEMA'))
);
INSERT INTO promotion_targets(promotion_id,target_type,target_value)
