-- ============================================================
-- BOOKINGS
-- ============================================================
CREATE TABLE bookings (
    booking_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_ref VARCHAR(30) NOT NULL UNIQUE,
    user_id BIGINT NOT NULL REFERENCES users(user_id),
    showtime_id BIGINT NOT NULL REFERENCES showtimes(showtime_id),
    ticket_quantity INTEGER DEFAULT 1 NOT NULL,
    ticket_price NUMERIC(10,2) NOT NULL,
    total_amount NUMERIC(10,2) NOT NULL,
    status VARCHAR(30) DEFAULT 'CONFIRMED' NOT NULL,
    booking_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at TIMESTAMP,
    promotion_id BIGINT REFERENCES promotions(promotion_id),
    discount_amount NUMERIC(10,2) DEFAULT 0 NOT NULL,
    expires_at TIMESTAMP,
    receipt_email VARCHAR(255),
    confirmation_sent_at TIMESTAMP,
    CONSTRAINT ck_bookings_quantity CHECK(ticket_quantity > 0),
    CONSTRAINT ck_bookings_price CHECK(ticket_price >= 0),
    CONSTRAINT ck_bookings_total CHECK(total_amount >= 0),
    CONSTRAINT ck_bookings_status CHECK(status IN('PENDING','CONFIRMED','CANCELLED','COMPLETED')),
    CONSTRAINT ck_bookings_discount CHECK(discount_amount >= 0)
);
CREATE INDEX idx_bookings_user ON bookings(user_id);
CREATE INDEX idx_bookings_showtime ON bookings(showtime_id);
CREATE INDEX idx_bookings_status ON bookings(status);
CREATE INDEX idx_bookings_user_date ON bookings(user_id, booking_date DESC);
CREATE INDEX idx_bookings_expires_at ON bookings(expires_at);

CREATE TABLE booking_tickets (
    booking_ticket_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id BIGINT NOT NULL REFERENCES bookings(booking_id),
    ticket_type VARCHAR(30) NOT NULL,
    quantity INTEGER NOT NULL,
    unit_price NUMERIC(10,2) NOT NULL,
    subtotal NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_booking_tickets_quantity CHECK(quantity > 0),
    CONSTRAINT ck_booking_tickets_unit_price CHECK(unit_price >= 0),
    CONSTRAINT ck_booking_tickets_subtotal CHECK(subtotal >= 0)
);
CREATE INDEX idx_booking_tickets_booking ON booking_tickets(booking_id);

CREATE TABLE booking_seats (
    booking_seat_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    booking_id BIGINT NOT NULL REFERENCES bookings(booking_id) ON DELETE CASCADE,
    showtime_id BIGINT NOT NULL REFERENCES showtimes(showtime_id),
    seat_id BIGINT NOT NULL REFERENCES seats(seat_id),
    ticket_price NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    -- No UNIQUE(showtime_id, seat_id): cancelled and expired bookings keep
    -- their rows for history, and their seats must be bookable again.
    -- createBooking() locks the showtime and checks live bookings itself.
    CONSTRAINT ck_booking_seats_price CHECK(ticket_price >= 0)
);
CREATE INDEX idx_booking_seats_booking ON booking_seats(booking_id);
CREATE INDEX idx_booking_seats_showtime ON booking_seats(showtime_id);
CREATE INDEX idx_booking_seats_seat ON booking_seats(seat_id);
CREATE INDEX idx_booking_seats_showtime_seat ON booking_seats(showtime_id, seat_id);

