-- ============================================================
-- UPDATED_AT FUNCTION / TRIGGER
-- ============================================================
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'customer_profiles','staff_profiles','cinemas','screens','studios','genres',
        'people','movies','production_companies','showtimes','ticket_prices',
        'promotions','bookings','payments','tickets','movie_reviews',
        'user_preferences','user_notification_preferences'
    ] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS trg_%I_updated_at ON %I',t,t);
        EXECUTE format('CREATE TRIGGER trg_%I_updated_at BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION set_updated_at()',t,t);
    END LOOP;
END $$;

-- ============================================================
-- MOVIE STATUS (run length)
-- UPCOMING before release_date, NOW_SHOWING for movie_run_weeks
-- (app_settings, default 12) or until movies.run_ends_on, then
-- ENDED. ARCHIVED is set by hand and never changed. The backend
-- calls refresh_movie_statuses() at start-up and hourly.
-- ============================================================
CREATE TABLE IF NOT EXISTS app_settings (
    setting_key   VARCHAR(100) PRIMARY KEY,
    setting_value VARCHAR(500) NOT NULL,
    description   VARCHAR(500),
    updated_at    TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);

INSERT INTO app_settings (setting_key, setting_value, description) VALUES
    ('movie_run_weeks', '12',
     'Weeks a film stays NOW_SHOWING after its release date, unless movies.run_ends_on is set')
ON CONFLICT (setting_key) DO NOTHING;

CREATE OR REPLACE FUNCTION movie_run_weeks()
RETURNS INTEGER
LANGUAGE sql
STABLE
AS $$
    SELECT COALESCE(
        (SELECT setting_value::INTEGER
           FROM app_settings
          WHERE setting_key = 'movie_run_weeks'
            AND setting_value ~ '^[0-9]{1,3}$'),
        12
    );
$$;


-- Last day a film is NOW_SHOWING (NULL if the release date is unknown)
CREATE OR REPLACE FUNCTION movie_run_end(p_release_date DATE, p_run_ends_on DATE)
RETURNS DATE
LANGUAGE sql
STABLE
AS $$
    SELECT CASE
        WHEN p_release_date IS NULL THEN NULL
        ELSE COALESCE(p_run_ends_on, p_release_date + (movie_run_weeks() * 7 - 1))
    END;
$$;


-- Status of a film on a given day
CREATE OR REPLACE FUNCTION movie_status_on(p_release_date DATE, p_run_ends_on DATE, p_on DATE)
RETURNS VARCHAR
LANGUAGE sql
STABLE
AS $$
    SELECT CASE
        WHEN p_release_date IS NULL OR p_release_date > p_on THEN 'UPCOMING'
        WHEN p_on <= movie_run_end(p_release_date, p_run_ends_on) THEN 'NOW_SHOWING'
        ELSE 'ENDED'
    END;
$$;


-- Kept for anything that still calls the old one-argument version
CREATE OR REPLACE FUNCTION calculate_movie_status(p_release_date DATE)
RETURNS VARCHAR
LANGUAGE sql
STABLE
AS $$
    SELECT movie_status_on(p_release_date, NULL, CURRENT_DATE);
$$;


-- ------------------------------------------------------------
-- 4. Trigger: recalculate whenever the dates (or status) are written,
--    except for films archived by hand
-- ------------------------------------------------------------

CREATE OR REPLACE FUNCTION trg_movies_status()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status = 'ARCHIVED' THEN
        RETURN NEW;
    END IF;

    NEW.status := movie_status_on(NEW.release_date, NEW.run_ends_on, CURRENT_DATE);
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_movies_status
    BEFORE INSERT OR UPDATE OF release_date, run_ends_on, status
    ON movies
    FOR EACH ROW
    EXECUTE FUNCTION trg_movies_status();

CREATE OR REPLACE FUNCTION refresh_movie_statuses()
RETURNS INTEGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_changed INTEGER;
BEGIN
    UPDATE movies
       SET status = movie_status_on(release_date, run_ends_on, CURRENT_DATE)
     WHERE status <> 'ARCHIVED'
       AND status IS DISTINCT FROM movie_status_on(release_date, run_ends_on, CURRENT_DATE);

    GET DIAGNOSTICS v_changed = ROW_COUNT;
    RETURN v_changed;
END;
$$;

-- ============================================================
-- SHOWTIME END TIME
-- ============================================================
CREATE OR REPLACE FUNCTION calculate_showtime_end()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_runtime INTEGER;
BEGIN
    SELECT runtime_minutes INTO v_runtime
    FROM movies
    WHERE movie_id = NEW.movie_id;

    IF v_runtime IS NOT NULL AND NEW.start_time IS NOT NULL THEN
        NEW.end_time := NEW.start_time + make_interval(mins => v_runtime);
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_showtimes_end_time
BEFORE INSERT OR UPDATE OF start_time,movie_id ON showtimes
FOR EACH ROW EXECUTE FUNCTION calculate_showtime_end();

-- ============================================================
-- BOOKING TOTAL
-- ============================================================
CREATE OR REPLACE FUNCTION calculate_booking_total()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.total_amount := GREATEST((NEW.ticket_quantity * NEW.ticket_price) - COALESCE(NEW.discount_amount,0),0);
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_bookings_total
BEFORE INSERT OR UPDATE OF ticket_quantity,ticket_price,discount_amount ON bookings
FOR EACH ROW EXECUTE FUNCTION calculate_booking_total();

-- ============================================================
-- PAYMENT / TICKET TIMESTAMPS
-- ============================================================
CREATE OR REPLACE FUNCTION update_payment_date()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status = 'COMPLETED' AND COALESCE(OLD.status,'') <> 'COMPLETED' THEN
        NEW.payment_date := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_payments_completed
BEFORE UPDATE ON payments
FOR EACH ROW EXECUTE FUNCTION update_payment_date();

CREATE OR REPLACE FUNCTION update_ticket_used_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.status = 'USED' AND COALESCE(OLD.status,'') <> 'USED' THEN
        NEW.used_at := CURRENT_TIMESTAMP;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_tickets_used
BEFORE UPDATE ON tickets
FOR EACH ROW EXECUTE FUNCTION update_ticket_used_at();

COMMIT;

