-- 2. 2026-11-19_events.sql -----------------------------
-- ============================================================
-- SAVANNAH CINEMAS - EVENTS
-- 2026-11-19_events.sql
--
-- Events shown on the app's Events tab (with the live promotions and
-- the coming-soon opening days). An event is either one-off
-- (starts_at) or weekly (weekday 1=Mon..7=Sun + start_time), and can
-- point at a film (movie_id) so the app links to it.
--
-- The two rows below are SAMPLES to show the layout. Edit them,
-- deactivate them (is_active = FALSE) or delete them.
-- Safe to run more than once.
-- ============================================================

CREATE TABLE IF NOT EXISTS cinema_events (
    event_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cinema_id   BIGINT REFERENCES cinemas(cinema_id),
    title       VARCHAR(150) NOT NULL,
    summary     VARCHAR(300),
    details     VARCHAR(2000),
    tag         VARCHAR(30),
    starts_at   TIMESTAMP,
    weekday     SMALLINT,
    start_time  TIME,
    ends_on     DATE,
    movie_id    BIGINT REFERENCES movies(movie_id) ON DELETE SET NULL,
    sort_order  INTEGER DEFAULT 0 NOT NULL,
    is_active   BOOLEAN DEFAULT TRUE NOT NULL,
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_cinema_events_when CHECK (starts_at IS NOT NULL OR (weekday BETWEEN 1 AND 7 AND start_time IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS idx_cinema_events_active ON cinema_events (is_active, starts_at);

INSERT INTO cinema_events (cinema_id, title, summary, details, tag, weekday, start_time, sort_order)
SELECT c.cinema_id, e.title, e.summary, e.details, e.tag, e.weekday, e.start_time::time, e.sort_order
FROM (SELECT cinema_id FROM cinemas WHERE cinema_name ILIKE '%Accra%' ORDER BY cinema_id LIMIT 1) c
CROSS JOIN (VALUES
    ('Family Saturday Mornings',
     'Saturday mornings lean towards family films.',
     'Saturday''s first shows favour films rated G and PG, so it''s an easy morning out with the kids. Book as usual from Tonight or Films. (Sample event: edit or delete in cinema_events.)',
     'FAMILY', 6, '10:00', 10),
    ('Late Night Thrillers',
     'Friday''s last shows are for grown-ups.',
     'The late Friday shows lean towards R and 18-rated films. Bring ID: staff may check it at the door. (Sample event: edit or delete in cinema_events.)',
     'LATE NIGHT', 5, '22:00', 20)
) AS e(title, summary, details, tag, weekday, start_time, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM cinema_events x WHERE x.title = e.title);


-- 2. 2026-11-19_screens_and_location.sql ---------------
-- ============================================================
-- SAVANNAH CINEMAS - MORE SCREENS, SEAT PLANS, ACCRA MALL
-- 2026-11-19_screens_and_location.sql
--
-- 1. The Accra cinema's address is Accra Mall (used by Directions,
--    Help and the confirmation email).
-- 2. Screens 3 and 4, so films can play on two or three screens.
-- 3. A seat plan for any screen that has none. Screen 2 (VIP) was
--    created by the setup script without seats, so its shows
--    couldn't be booked.
--
-- Safe to run more than once: nothing is duplicated, and screens
-- that already have seats are left alone.
-- ============================================================


-- 1. Address ----------------------------------------------------

UPDATE cinemas
SET address    = 'Accra Mall, Plot C11, Tetteh Quarshie Interchange, Spintex Road',
    city       = 'Accra',
    region     = 'Greater Accra',
    updated_at = CURRENT_TIMESTAMP
WHERE cinema_name ILIKE '%Accra%'
  AND COALESCE(address, '') NOT ILIKE '%Accra Mall%';


-- 2. Screens 3 and 4 ---------------------------------------------

INSERT INTO screens (cinema_id, screen_name, screen_number, capacity, screen_type, sound_system)
SELECT c.cinema_id, s.name, s.num, 1, 'STANDARD', s.sound
FROM cinemas c
CROSS JOIN (VALUES
    ('Screen 3', 3, 'Dolby Digital'),
    ('Screen 4', 4, 'Dolby Digital')
) AS s(name, num, sound)
WHERE c.cinema_name ILIKE '%Accra%'
ON CONFLICT (cinema_id, screen_number) DO NOTHING;


-- 3. Seat plans for screens without seats -----------------------
--    VIP screen:      rows A-D x 8, all VIP, + 2 wheelchair spaces
--    Standard screen: rows A-H x 12 (Screen 3) or A-F x 10 (others),
--                     the two back rows' centre seats VIP,
--                     + 2 wheelchair spaces

DO $$
DECLARE
    sc RECORD;
    n_rows INT;
    n_seats INT;
BEGIN
    FOR sc IN
        SELECT s.screen_id, s.screen_number, UPPER(COALESCE(s.screen_type, '')) AS screen_type
        FROM screens s
        WHERE s.is_active = 'Y'
          AND NOT EXISTS (SELECT 1 FROM seats se WHERE se.screen_id = s.screen_id)
    LOOP
        IF sc.screen_type = 'VIP' THEN
            n_rows := 4; n_seats := 8;
        ELSIF sc.screen_number = 3 THEN
            n_rows := 8; n_seats := 12;
        ELSE
            n_rows := 6; n_seats := 10;
        END IF;

        INSERT INTO seats (screen_id, row_label, seat_number, seat_label, seat_type)
        SELECT sc.screen_id,
               chr(64 + r),
               n,
               chr(64 + r) || n::text,
               CASE
                   WHEN sc.screen_type = 'VIP' THEN 'VIP'
                   WHEN r > n_rows - 2 AND n BETWEEN (n_seats / 2 - 1) AND (n_seats / 2 + 2) THEN 'VIP'
                   ELSE 'STANDARD'
               END
        FROM generate_series(1, n_rows) AS r
        CROSS JOIN generate_series(1, n_seats) AS n;

        INSERT INTO seats (screen_id, row_label, seat_number, seat_label, seat_type)
        VALUES (sc.screen_id, 'W', 1, 'W1', 'WHEELCHAIR'),
               (sc.screen_id, 'W', 2, 'W2', 'WHEELCHAIR');

        UPDATE screens
        SET capacity = (SELECT COUNT(*) FROM seats WHERE screen_id = sc.screen_id)
        WHERE screen_id = sc.screen_id;
    END LOOP;
END $$;


-- 2. 2026-11-20_rewards.sql ----------------------------
-- ============================================================
-- SAVANNAH CINEMAS - REWARDS (points, trophies, referrals)
-- 2026-11-20_rewards.sql
--
-- Points are worked out from bookings by services/rewards.js, so
-- cancelling a booking takes its points away and refunds any points
-- spent on it automatically. This migration adds what can't be
-- worked out:
--   - users.referral_code      each member's code to share
--   - referrals                who brought whom
--   - user_trophies            trophies once earned are kept
--   - bookings.points_redeemed / points_discount   points spent at checkout
--   - movies.collection_* / production_countries / original_language
--                              (filled by the TMDB sync) for the
--                              Franchise Fan and Made in Ghana trophies
-- Safe to run more than once.
-- ============================================================

ALTER TABLE users ADD COLUMN IF NOT EXISTS referral_code VARCHAR(16);
CREATE UNIQUE INDEX IF NOT EXISTS uk_users_referral_code ON users (referral_code);

CREATE TABLE IF NOT EXISTS referrals (
    referral_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    referrer_id  BIGINT NOT NULL REFERENCES users(user_id),
    referred_id  BIGINT NOT NULL UNIQUE REFERENCES users(user_id),
    created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT ck_referrals_self CHECK (referrer_id <> referred_id)
);
CREATE INDEX IF NOT EXISTS idx_referrals_referrer ON referrals (referrer_id);

CREATE TABLE IF NOT EXISTS user_trophies (
    user_id     BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    trophy_code VARCHAR(40) NOT NULL,
    earned_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    booking_id  BIGINT REFERENCES bookings(booking_id) ON DELETE SET NULL,
    seen_at     TIMESTAMP,
    PRIMARY KEY (user_id, trophy_code)
);

ALTER TABLE bookings ADD COLUMN IF NOT EXISTS points_redeemed INTEGER DEFAULT 0 NOT NULL;
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS points_discount NUMERIC(10,2) DEFAULT 0 NOT NULL;

ALTER TABLE movies ADD COLUMN IF NOT EXISTS collection_id INTEGER;
ALTER TABLE movies ADD COLUMN IF NOT EXISTS collection_name VARCHAR(200);
ALTER TABLE movies ADD COLUMN IF NOT EXISTS production_countries VARCHAR(200);
ALTER TABLE movies ADD COLUMN IF NOT EXISTS original_language VARCHAR(10);
CREATE INDEX IF NOT EXISTS idx_movies_collection ON movies (collection_id);


-- 2. 2026-11-21_notifications.sql ----------------------
-- ============================================================
-- SAVANNAH CINEMAS - NOTIFICATIONS & FILM REMINDERS
-- 2026-11-21_notifications.sql
--
-- user_notifications  the in-app inbox (bell in Account). Rows are
--                     created by services/notifications.js:
--                     booking reminders (3 h and 30 min before),
--                     opening-day / on-sale alerts for films a member
--                     asked to be reminded about, new trophies.
-- film_reminders      "remind me" on coming-soon films (bell icon).
-- Safe to run more than once.
-- ============================================================

CREATE TABLE IF NOT EXISTS user_notifications (
    notification_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    kind            VARCHAR(30) NOT NULL,
    title           VARCHAR(160) NOT NULL,
    body            VARCHAR(500),
    data            JSONB DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key      VARCHAR(160) NOT NULL,
    deliver_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    read_at         TIMESTAMP,
    CONSTRAINT uk_user_notifications_dedupe UNIQUE (user_id, dedupe_key)
);

CREATE INDEX IF NOT EXISTS idx_user_notifications_inbox
    ON user_notifications (user_id, deliver_at DESC);

CREATE TABLE IF NOT EXISTS film_reminders (
    user_id     BIGINT NOT NULL REFERENCES users(user_id) ON DELETE CASCADE,
    movie_id    BIGINT NOT NULL REFERENCES movies(movie_id) ON DELETE CASCADE,
    created_at  TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY (user_id, movie_id)
);


-- 2. 2026-11-22_profile_look.sql -----------------------
-- ============================================================
-- SAVANNAH CINEMAS - USERNAME, AVATAR, PROFILE BACKDROP
-- 2026-11-22_profile_look.sql
--
-- username       shown on the profile as @name. Unique, not case
--                sensitive. New accounts get a generated one
--                (e.g. VelvetCritic27) that they can change.
-- avatar_key     one of the app's preset avatars ('lion', 'owl', ...)
-- profile_backdrop_movie_id / _url
--                a film still chosen as the profile header
--
-- Existing accounts get a username from their first name and user
-- id (e.g. ama_12) so every account has one.
-- Safe to run more than once.
-- ============================================================

ALTER TABLE users ADD COLUMN IF NOT EXISTS username VARCHAR(30);
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_key VARCHAR(40);
ALTER TABLE users ADD COLUMN IF NOT EXISTS profile_backdrop_url VARCHAR(500);
ALTER TABLE users ADD COLUMN IF NOT EXISTS profile_backdrop_movie_id BIGINT;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_users_backdrop_movie') THEN
        ALTER TABLE users
            ADD CONSTRAINT fk_users_backdrop_movie
            FOREIGN KEY (profile_backdrop_movie_id) REFERENCES movies(movie_id) ON DELETE SET NULL;
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uk_users_username_lower ON users (LOWER(username));

UPDATE users
SET username = COALESCE(NULLIF(LEFT(regexp_replace(LOWER(forenames), '[^a-z0-9]', '', 'g'), 14), ''), 'fan') || '_' || user_id::text
WHERE username IS NULL;


-- 2. 2026-11-22_west_hills.sql -------------------------
-- ============================================================
-- SAVANNAH CINEMAS - SECOND LOCATION: WEST HILLS MALL
-- 2026-11-22_west_hills.sql
--
-- 1. The Accra cinema is renamed "Savannah Cinemas - Accra Mall" so
--    the app can tell the two locations apart.
-- 2. "Savannah Cinemas - West Hills Mall" (Dunkonah, Weija, off the
--    Accra - Cape Coast Highway) with three screens and seat plans.
-- 3. Ticket prices for West Hills, copied from Accra Mall.
-- 4. The sample weekly events, copied to West Hills.
--
-- After running this, generate showtimes (npm run showtimes:generate, or wait
-- for the 6-hourly job): the generator now programmes each cinema
-- separately, so West Hills gets its own shows.
--
-- Phone and email below are placeholders: put in the real ones.
-- Safe to run more than once.
-- ============================================================


-- 1. Accra Mall name -----------------------------------------------

UPDATE cinemas
SET cinema_name = 'Savannah Cinemas - Accra Mall',
    updated_at  = CURRENT_TIMESTAMP
WHERE cinema_name ILIKE '%Accra%'
  AND cinema_name NOT ILIKE '%Accra Mall%'
  AND COALESCE(address, '') ILIKE '%Accra Mall%';


-- 2. West Hills Mall -----------------------------------------------

INSERT INTO cinemas (cinema_name, description, address, city, region, phone_number, email, is_active)
SELECT 'Savannah Cinemas - West Hills Mall',
       'Savannah Cinemas on the west side of Accra',
       'West Hills Mall, Dunkonah, Weija, off the Accra - Cape Coast Highway',
       'Accra',
       'Greater Accra',
       '+233 20 000 0001',
       'westhills@savannahcinemas.com',
       'Y'
WHERE NOT EXISTS (SELECT 1 FROM cinemas WHERE cinema_name ILIKE '%West Hills%');

INSERT INTO screens (cinema_id, screen_name, screen_number, capacity, screen_type, sound_system)
SELECT c.cinema_id, s.name, s.num, 1, s.type, s.sound
FROM cinemas c
CROSS JOIN (VALUES
    ('Screen 1', 1, 'STANDARD', 'Dolby Digital'),
    ('Screen 2', 2, 'VIP',      'Dolby Atmos'),
    ('Screen 3', 3, 'STANDARD', 'Dolby Digital')
) AS s(name, num, type, sound)
WHERE c.cinema_name ILIKE '%West Hills%'
ON CONFLICT (cinema_id, screen_number) DO NOTHING;

--    Seat plans for the new screens (same layouts as Accra Mall):
--    VIP rows A-D x 8; Screen 3 rows A-H x 12; Screen 1 rows A-F x 10;
--    standard screens get VIP centre seats in the back two rows;
--    every screen gets two wheelchair spaces.
DO $$
DECLARE
    sc RECORD;
    n_rows INT;
    n_seats INT;
BEGIN
    FOR sc IN
        SELECT s.screen_id, s.screen_number, UPPER(COALESCE(s.screen_type, '')) AS screen_type
        FROM screens s
        JOIN cinemas c ON c.cinema_id = s.cinema_id
        WHERE c.cinema_name ILIKE '%West Hills%'
          AND NOT EXISTS (SELECT 1 FROM seats se WHERE se.screen_id = s.screen_id)
    LOOP
        IF sc.screen_type = 'VIP' THEN
            n_rows := 4; n_seats := 8;
        ELSIF sc.screen_number = 3 THEN
            n_rows := 8; n_seats := 12;
        ELSE
            n_rows := 6; n_seats := 10;
        END IF;

        INSERT INTO seats (screen_id, row_label, seat_number, seat_label, seat_type)
        SELECT sc.screen_id,
               chr(64 + r),
               n,
               chr(64 + r) || n::text,
               CASE
                   WHEN sc.screen_type = 'VIP' THEN 'VIP'
                   WHEN r > n_rows - 2 AND n BETWEEN (n_seats / 2 - 1) AND (n_seats / 2 + 2) THEN 'VIP'
                   ELSE 'STANDARD'
               END
        FROM generate_series(1, n_rows) AS r
        CROSS JOIN generate_series(1, n_seats) AS n;

        INSERT INTO seats (screen_id, row_label, seat_number, seat_label, seat_type)
        VALUES (sc.screen_id, 'W', 1, 'W1', 'WHEELCHAIR'),
               (sc.screen_id, 'W', 2, 'W2', 'WHEELCHAIR');

        UPDATE screens
        SET capacity = (SELECT COUNT(*) FROM seats WHERE screen_id = sc.screen_id)
        WHERE screen_id = sc.screen_id;
    END LOOP;
END $$;


-- 3. Ticket prices (copied from Accra Mall's cinema-wide prices) ---

INSERT INTO ticket_prices (cinema_id, screen_id, price_name, ticket_type, amount, currency, day_type, start_time, end_time, is_active)
SELECT wh.cinema_id, NULL, p.price_name, p.ticket_type, p.amount, p.currency, p.day_type, p.start_time, p.end_time, p.is_active
FROM ticket_prices p
JOIN cinemas am ON am.cinema_id = p.cinema_id AND am.cinema_name ILIKE '%Accra Mall%'
CROSS JOIN (SELECT cinema_id FROM cinemas WHERE cinema_name ILIKE '%West Hills%' ORDER BY cinema_id LIMIT 1) wh
WHERE p.screen_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM ticket_prices x WHERE x.cinema_id = wh.cinema_id);


-- 4. Sample weekly events at West Hills too ------------------------

DO $$
BEGIN
    IF to_regclass('public.cinema_events') IS NOT NULL THEN
        INSERT INTO cinema_events (cinema_id, title, summary, details, tag, weekday, start_time, ends_on, movie_id, sort_order, is_active)
        SELECT wh.cinema_id, e.title, e.summary, e.details, e.tag, e.weekday, e.start_time, e.ends_on, e.movie_id, e.sort_order, e.is_active
        FROM cinema_events e
        JOIN cinemas am ON am.cinema_id = e.cinema_id AND am.cinema_name ILIKE '%Accra Mall%'
        CROSS JOIN (SELECT cinema_id FROM cinemas WHERE cinema_name ILIKE '%West Hills%' ORDER BY cinema_id LIMIT 1) wh
        WHERE e.weekday IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM cinema_events x WHERE x.cinema_id = wh.cinema_id AND x.title = e.title);
    END IF;
END $$;


-- 2. 2026-11-23_snack_upgrades.sql ---------------------
-- ============================================================
-- SAVANNAH CINEMAS - BIGGER SNACK MENU AND UPGRADES
